PRAGMA foreign_keys=ON;
CREATE TABLE SimulationRun(run_id TEXT PRIMARY KEY,random_seed INTEGER NOT NULL,mode TEXT NOT NULL CHECK(mode IN('unit_test','smoke_test','calibration','production')),scenario TEXT NOT NULL,created_at TEXT NOT NULL,disclaimer TEXT NOT NULL);
CREATE TABLE UserSynthetic(user_id TEXT PRIMARY KEY,pair_id TEXT NOT NULL,sample_set_type TEXT NOT NULL CHECK(sample_set_type IN('control','treatment')),sample_stratum TEXT NOT NULL,simulation_run_id TEXT NOT NULL REFERENCES SimulationRun(run_id),random_seed INTEGER NOT NULL,source_session_id TEXT NOT NULL,treatment_scenario TEXT NOT NULL,generation_model_version TEXT NOT NULL,age_group TEXT CHECK(age_group IS NULL),UNIQUE(pair_id,sample_set_type),CHECK((sample_set_type='control' AND treatment_scenario='none') OR (sample_set_type='treatment' AND treatment_scenario IN('conservative','expected','optimistic'))));
CREATE TABLE SessionSynthetic(session_id TEXT PRIMARY KEY,user_id TEXT NOT NULL UNIQUE REFERENCES UserSynthetic(user_id),pair_id TEXT NOT NULL,started_at TEXT NOT NULL,ended_at TEXT NOT NULL,outcome_segment TEXT NOT NULL CHECK(outcome_segment IN('SG1','SG2','SG3','SG4')),treatment_exposed INTEGER NOT NULL CHECK(treatment_exposed IN(0,1)));
CREATE TABLE Hotel(hotel_id TEXT PRIMARY KEY,hotel_name TEXT NOT NULL);
CREATE TABLE Room(room_id TEXT PRIMARY KEY,hotel_id TEXT NOT NULL REFERENCES Hotel(hotel_id));
CREATE TABLE Search(search_id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES SessionSynthetic(session_id),search_sequence INTEGER NOT NULL,search_time TEXT NOT NULL,total_result_count INTEGER NOT NULL CHECK(total_result_count>=0),query_text TEXT NOT NULL,destination TEXT NOT NULL,action_type TEXT NOT NULL,UNIQUE(session_id,search_sequence));
CREATE TABLE SearchFilter(search_filter_id TEXT PRIMARY KEY,search_id TEXT NOT NULL UNIQUE REFERENCES Search(search_id),price INTEGER,amenity_count INTEGER NOT NULL,region TEXT NOT NULL,property_type TEXT CHECK(property_type IS NULL),property_grade INTEGER CHECK(property_grade IS NULL));
CREATE TABLE SearchResult(search_result_id TEXT PRIMARY KEY,search_id TEXT NOT NULL REFERENCES Search(search_id),hotel_id TEXT NOT NULL REFERENCES Hotel(hotel_id),room_id TEXT NOT NULL REFERENCES Room(room_id),result_rank INTEGER NOT NULL CHECK(result_rank>0),UNIQUE(search_id,hotel_id),UNIQUE(search_id,result_rank));
CREATE TABLE ActionEvent(event_id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES UserSynthetic(user_id),session_id TEXT NOT NULL REFERENCES SessionSynthetic(session_id),search_id TEXT REFERENCES Search(search_id),hotel_id TEXT REFERENCES Hotel(hotel_id),event_type TEXT NOT NULL,event_at TEXT NOT NULL,review_completed_at TEXT CHECK(review_completed_at IS NULL),review_text TEXT CHECK(review_text IS NULL));
CREATE TABLE SearchTransition(transition_id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES SessionSynthetic(session_id),from_search_id TEXT NOT NULL REFERENCES Search(search_id),to_search_id TEXT NOT NULL REFERENCES Search(search_id),action_type TEXT NOT NULL,recovered INTEGER NOT NULL CHECK(recovered IN(0,1)));
CREATE TABLE _generation_metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE Booking(booking_id TEXT PRIMARY KEY,user_id TEXT REFERENCES UserSynthetic(user_id),hotel_id TEXT REFERENCES Hotel(hotel_id),room_id TEXT REFERENCES Room(room_id));
CREATE INDEX idx_search_session_time ON Search(session_id,search_time);
CREATE INDEX idx_event_session_time ON ActionEvent(session_id,event_at);
CREATE INDEX idx_event_search_type ON ActionEvent(search_id,event_type);
CREATE INDEX idx_result_search_rank ON SearchResult(search_id,result_rank);
